    q17054: { h: "1085bb8f254f", text: "In a shrimp pond, one virus sinks the whole crop: would you get up again after the virus loss?" },
    q17055: { h: "370efcf4b88e", text: "A bamboo grove becomes fit for cutting in three to four years: would you count the grove's years?" },
    q17056: { h: "f05134b4fe3f", text: "Teak is a trust of twenty to thirty years: would you plant a tree for the next generation?" },
    q17057: { h: "f0755c9dddc9", text: "A rubber tree gives its first latex after seven years: could you bear the seven-year wait for tapping?" },
    q17058: { h: "003b4f4269f5", text: "A coconut plant bears fruit in six to seven years: would you count the coconut's years?" },
    q17059: { h: "09c24ff02404", text: "The earnings from palm sap come drop by drop from the daily climb: could you bear earnings drop by drop?" },
    q17060: { h: "69b6ef5ecb79", text: "A cocoa plant gives pods after four years of care: would you wait for the pods?" },
    q17061: { h: "c6bde0d7051d", text: "Gum oozes out drop by drop over weeks: could you bear the weeks of oozing?" },
    q17062: { h: "edb46b0140e0", text: "The harvest cycle of paper-wood planting is eight to ten years: would you keep up the planting cycle?" },
    q17063: { h: "8ad70eed903c", text: "In a sawmill a consignment of logs sometimes gets stuck for weeks: could you put up with a stuck consignment?" },
    q17064: { h: "92307287c39d", text: "Cork bark can be peeled again only in nine to ten years: could you bear the decade of the bark?" },
    q17065: { h: "d58d51d34d0c", text: "The chilli rate goes sharply up and down: could you put up with the sharp swing?" },
    q17066: { h: "97d3d3c76066", text: "Turmeric ripens under the ground in the field for nine months: would you count the months under the ground?" },
    q17067: { h: "db46e070625f", text: "A cardamom plantation settles over years in cool shade: would you keep up the settling of the plantation?" },
    q17068: { h: "f3a30a46b79c", text: "A saffron bed gives flowers only a few days a year: could you bear having only a few days?" },
    q17069: { h: "3aecda9d7d9f", text: "A market of trust for herbs builds slowly: could you put up with the time trust takes?" },
    q17070: { h: "fecd55ffcf60", text: "In hemp, the licence papers keep you going round for months: could you bear the rounds of paperwork?" },
    q17071: { h: "ea42ccbdc76c", text: "Local customers for quinoa build up slowly: could you put up with the time new customers take?" },
    q17072: { h: "5d412170c87e", text: "The farm-to-shop link for stevia takes time to settle: could you bear the settling of the link?" },
    q17073: { h: "8b4dbbd61c48", text: "A vanilla pod ripens on the vine for nine months and then cures for months more: would you do the double wait?" },
    q17074: { h: "277cf5c68683", text: "Organic certification asks for three years of proof of farming: would you give three years of proof?" },
    q17075: { h: "0396d381a3f4", text: "The earnings of a mill add up paisa by paisa from grinding: could you bear paisa-by-paisa grinding?" },
    q17076: { h: "eccbe70af18e", text: "A customer of cold-press oil becomes firm only over months, after testing the taste: could you put up with the time of taste testing?" },
    q17077: { h: "41174a6c0d75", text: "In a milk plant the payment cycle turns every fortnight: could you bear the fortnight cycle?" },
    q17078: { h: "9d78dbd03382", text: "In a meat unit the inspection approval runs long: could you put up with the long approval?" },
    q17079: { h: "712a57b4f6ab", text: "Drying fish gets stuck on the kindness of the weather: could you bear being stuck on the weather?" },
    q17080: { h: "60611e5852b4", text: "The name of a jam brand climbs slowly in the shops: could you put up with the time the name takes to climb?" },
    q17081: { h: "07ebfb8fbd01", text: "The file for a brewery licence travels from office to office: could you bear the travels of the file?" },
    q17082: { h: "fe2f1bbb7a5c", text: "The right recipe for chocolate asks for a hundred trials: would you do a hundred trials?" },
    q17083: { h: "eb99e6f6d634", text: "Steady customers for a bakery's dawn hard work build up over months: would you keep up the dawn period?" },
    q17084: { h: "eae78653123a", text: "In the frozen business, nights of power cuts are frightening: could you put up with the fear of power cuts?" },
    q17085: { h: "b272fc8b877f", text: "A batch of pickle is ready only after ripening in the sun for weeks: would you count the weeks of ripening?" },
    q17086: { h: "82669006dda2", text: "The identity of a spice brand settles slowly in the market: could you bear the time identity takes?" },
    q17087: { h: "de519f0179dd", text: "Collecting credit dues at a feed mill drags on for a month: could you put up with the drag of credit?" },
    q17088: { h: "5d67fd0ddd81", text: "In the flower business, unsold garlands wilt by evening: could you bear the wilted evening?" },
    q17089: { h: "6d50a1d85a5a", text: "The paddy-and-fish pair asks for a double wait for two crops: would you do the double wait?" },
    q17090: { h: "0ef20353e3a9", text: "The traditional earnings of an old-style press are slow in the new market: would you keep up the slow tradition?" },
    q17091: { h: "e817418dded0", text: "A polyhouse takes two to three years to return its cost: would you count the years of cost?" },
    q17975: { h: "8c66c9231293", text: "If a rice mill joins up with paddy, the rice goes straight into the sack: would you build the paddy-and-mill pair?" },
    q17976: { h: "bd02f7533c6b", text: "The pair of wheat with a flour mill reaches the bread of every home: would you like the wheat-and-mill pair?" },
    q17977: { h: "4a62dec39b90", text: "If maize joins up with poultry feed, a farm-to-feed link is made: would you think of the maize-and-feed link?" },
    q17978: { h: "cd669eb3072e", text: "If a pulse mill sits next to pulse farming, both shine: would you enjoy the pulse-and-mill neighbourhood?" },
    q17979: { h: "2971a272fda8", text: "If oilseeds and the oil press are together, the oil flows straight: would you like oilseeds and the press together?" },
    q17980: { h: "05c770971725", text: "A jaggery furnace along with sugarcane is an old, proven pair: would you build the sugarcane-and-jaggery pair?" },
    q17981: { h: "48cc9b19880e", text: "A ginning unit next to cotton cleans the lint: would you think of the cotton-and-ginning neighbourhood?" },
    q17982: { h: "c5c8c6c0ee56", text: "A sack-weaving unit along with jute uses up the goods right there: would you enjoy jute and sacks together?" },
