    q17987: { h: "ab50b99984d3", text: "Raisin drying next to grapes becomes insurance against the weather: would you think of the grape-and-raisin neighbourhood?" },
    q17988: { h: "2f67e59706c0", text: "If a cold store joins up with apples, waiting for the rate becomes possible: would you enjoy the apple-and-store pair?" },
