    q17990: { h: "6526ea8e55da", text: "An orchard advice service along with an avocado nursery holds on to sapling customers: would you think of the nursery-and-advice pair?" },
    q17991: { h: "a97cd4a2b618", text: "A roasting and packing unit next to cashew doubles the price: would you enjoy the cashew-and-packing neighbourhood?" },
